// --- Interaction & Flip Logic ---
let selectedTile = null;
let dragStartTile = null;
let isPointerDown = false;
export let isAnimating = false;
export const activeTweens = [];
export let stepCount = 0;
export let completedZones = new Set();

export let levelWon = false;
let onWinCallback = null;
export function setOnWinCallback(cb) { onWinCallback = cb; }

export let isSingleFlipActive = false;
let onSingleFlipConsumed = null;
export function setOnSingleFlipConsumed(cb) { onSingleFlipConsumed = cb; }

export function toggleSingleFlipMode() {
    isSingleFlipActive = !isSingleFlipActive;
    const btn = document.getElementById('btn-single-flip');
    if (btn) btn.classList.toggle('active-tool', isSingleFlipActive);
    if (isSingleFlipActive && isSingleRotateActive) {
        toggleSingleRotateMode();
    }
}

export let isSingleRotateActive = false;
let onSingleRotateConsumed = null;
export function setOnSingleRotateConsumed(cb) { onSingleRotateConsumed = cb; }

export function toggleSingleRotateMode() {
    isSingleRotateActive = !isSingleRotateActive;
    const btn = document.getElementById('btn-single-rotate');
    if (btn) btn.classList.toggle('active-tool', isSingleRotateActive);
    if (isSingleRotateActive && isSingleFlipActive) {
        toggleSingleFlipMode();
    }
}

export function getCompletedZones() {
    return completedZones.size;
}

export function resetInteractionState() {
    stepCount = 0;
    completedZones.clear();
    isAnimating = false;
    activeTweens.length = 0; // safely clear ongoing animations
    selectedTile = null;
    dragStartTile = null;
    isPointerDown = false;
    levelWon = false;

    isSingleFlipActive = false;
    const flipBtn = document.getElementById('btn-single-flip');
    if (flipBtn) flipBtn.classList.remove('active-tool');
    
    isSingleRotateActive = false;
    const rotateBtn = document.getElementById('btn-single-rotate');
    if (rotateBtn) rotateBtn.classList.remove('active-tool');

    clearHints(); // Make sure a restarted level drops the hint state

    const stepDisplay = document.getElementById('step-count-display');
    if (stepDisplay && levelConfig) {
        stepDisplay.innerText = `Steps: ${stepCount}`;
    }
    const levelDisplay = document.getElementById('level-number-display');
    if (levelDisplay && levelConfig) {
        levelDisplay.innerText = levelConfig.levelNumber;
    }
}

function isFixedTile(tile) {
    if (!tile || !tile.userData || !tile.userData.type) return true;

    const type = tile.userData.type;
    if (type === '@@') return true;
    if (type.startsWith('T')) return true;
    if (tile.userData.isPathTarget) return true;
    if (tile.userData.freezeLevel > 0 && !completedZones.has(tile.userData.freezeLevel)) return true;

    const pathType = type.length > 2 ? type[2] : null;
    if (pathType && '012345'.includes(pathType)) return true;

    return false;
}

function isBlockedEdge(tileA, tileB) {
    let k1 = `${tileA.userData.q},${tileA.userData.r}`;
    let k2 = `${tileB.userData.q},${tileB.userData.r}`;
    let wallKey = k1 < k2 ? `${k1}|${k2}` : `${k2}|${k1}`;
    
    if (walls.has(wallKey)) return true;
    
    if (colorGates.has(wallKey)) {
        const allowedColors = colorGates.get(wallKey);
        
        const isTileAllowed = (tile) => {
            const type = tile.userData.type;
            if (type === '**' || type === '@@' || type.startsWith('T')) return true;
            
            const topColor = getCurrentColor(tile);
            return allowedColors.includes(topColor);
        };
        
        if (!isTileAllowed(tileA) || !isTileAllowed(tileB)) {
            return true;
        }
    }
    
    return false;
}

export function getPathAndRot(typeStr) {
    if (typeStr.length <= 2) return { path: null, rot: 0 };
    const lastChar = typeStr[typeStr.length - 1];
    let path = null;
    let rot = 0;
    if (/[0-5]/.test(lastChar)) {
        rot = parseInt(lastChar, 10);
        path = (typeStr.length > 3) ? typeStr[2] : '0';
        if (path === '*' || /[0-5]/.test(path)) path = '0';
    } else {
        path = typeStr[2];
        rot = 0;
    }
    return { path, rot };
}

export function isTileMatch(tile, rawExpectedType) {
    const cleanType = (t) => t.length > 2 ? t.substring(0, 2) + t.substring(2).replace(/\*+$/, '') : t;
    const currentType = tile.userData.type; // already cleaned upon tile creation
    const expectedType = cleanType(rawExpectedType);

    // Exact match OR scattered tile top-color match
    let isColorMatch = false;
    if (currentType === expectedType) {
        isColorMatch = true;
    } else if (currentType[0] !== 'T' && expectedType[0] !== 'T' && currentType !== '@@' && currentType !== '**' && expectedType !== '@@' && expectedType !== '**') {
        let expectedTop = expectedType[0] === 'T' ? expectedType[1] : expectedType[0];
        let currentTop = getCurrentColor(tile);
        if (currentTop === expectedTop) {
            isColorMatch = true;
        }
    }

    if (!isColorMatch) return false;

    if (expectedType.length <= 2) return true;

    const expected = getPathAndRot(expectedType);
    const current = getPathAndRot(currentType);

    if (current.path !== expected.path) return false;

    // Strict Rotation check
    if (expected.path) {
        const expectedRot = expected.rot;
        const currentRot = tile.userData.rotation !== undefined ? tile.userData.rotation : 0;
        const currentFlipped = tile.userData.flipped || false;

        const baseEdges = pathData[expected.path];
        if (!baseEdges) {
            const norm = (r) => ((r % 6) + 6) % 6;
            if (norm(currentRot) !== norm(expectedRot)) return false;
        } else {
            const mod = (n, m) => ((n % m) + m) % m;
            const getNormalizedEdges = (rot, flipped) => {
                const edges = baseEdges.map(segment => {
                    const e1 = segment[0] === 6 ? 6 : mod((flipped ? -segment[0] : segment[0]) + rot, 6);
                    const e2 = segment[1] === 6 ? 6 : mod((flipped ? -segment[1] : segment[1]) + rot, 6);
                    return e1 < e2 ? `${e1},${e2}` : `${e2},${e1}`;
                });
                return edges.sort().join('|');
            };
            if (getNormalizedEdges(currentRot, currentFlipped) !== getNormalizedEdges(expectedRot, false)) return false;
        }
    }

    return true;
}

export function getObjectiveState() {
    if (!levelConfig || !levelConfig.objective) return null;
    const obj = levelConfig.objective;
    const zonesConfig = levelConfig?.zones || {};
    const hasZones = Object.keys(zonesConfig).length > 0;

    const objMap = new Map();
    const zonesState = {};
    let maxZone = 1;
    let isWin = true;

    if (obj.pieces) {
        for (const p of obj.pieces) {
            objMap.set(`${p.q},${p.r}`, p.type);
            const z = hasZones ? (zonesConfig[`${p.q},${p.r}`] !== undefined ? zonesConfig[`${p.q},${p.r}`] : 0) : 1;
            if (z > maxZone) maxZone = z;
            if (!zonesState[z]) zonesState[z] = { matched: true };

            const tile = tiles.get(`${p.q},${p.r}`);
            if (!tile || !isTileMatch(tile, p.type)) {
                zonesState[z].matched = false;
                isWin = false;
            }
        }
    } else if (obj.map) {
        // Legacy behavior
        let halfRows = Math.floor(obj.map.length / 2);
        for (let i = 0; i < obj.map.length; i++) {
            let r = i - halfRows;
            const rowTiles = obj.map[i].trim().split(/\s+/).filter(t => t.length > 0);
            let N = rowTiles.length;
            if (N === 0) continue;
            let qStart = Math.floor(-r / 2 - (N - 1) / 2);
            for (let j = 0; j < N; j++) {
                let q = qStart + j;
                const expectedType = rowTiles[j];
                if (/^\*+$/.test(expectedType)) continue;
                
                objMap.set(`${q},${r}`, expectedType);
                const z = hasZones ? (zonesConfig[`${q},${r}`] !== undefined ? zonesConfig[`${q},${r}`] : 0) : 1;
                if (z > maxZone) maxZone = z;
                if (!zonesState[z]) zonesState[z] = { matched: true };
                const tile = tiles.get(`${q},${r}`);
                if (!tile || !isTileMatch(tile, expectedType)) {
                    zonesState[z].matched = false;
                    isWin = false;
                }
            }
        }
    }
    
    const sortedZones = Object.keys(zonesState).map(Number).sort((a, b) => a - b);
    let targetZone = sortedZones.length > 0 ? sortedZones[sortedZones.length - 1] : 1;
    for (const z of sortedZones) {
        if (!zonesState[z].matched) {
            targetZone = z;
            break;
        }
    }
    
    return { objMap, zonesState, maxZone, hasZones, isWin, sortedZones, targetZone };
}

export function evaluateLogicalWin(objMap) {
    const endpointsByColor = {};
    const pathColors = new Set();
    
    const cleanType = (t) => t.length > 2 ? t.substring(0, 2) + t.substring(2).replace(/\*+$/, '') : t;

    // Extract required endpoints by color
    for (const rawExpected of objMap.values()) {
        const expectedType = cleanType(rawExpected);
        if (expectedType.length > 2) {
            const { path } = getPathAndRot(expectedType);
            if (path === '0') {
                const color = expectedType[0];
                if (!endpointsByColor[color]) endpointsByColor[color] = [];
                pathColors.add(color);
            }
        }
    }

    for (const [key, rawExpected] of objMap.entries()) {
        const expectedType = cleanType(rawExpected);
        const { path, rot } = getPathAndRot(expectedType);
        if (path === '0') endpointsByColor[expectedType[0]].push({ key, color: expectedType[0], edge: rot });
    }

    // If no endpoints exist, the logical path fallback doesn't apply
    if (pathColors.size === 0) return false;

    // Verify all non-path tiles are strictly matched
    for (const [key, rawExpectedType] of objMap.entries()) {
        const expectedType = cleanType(rawExpectedType);
        const tile = tiles.get(key);
        if (!tile) return false;
        
        const expectedColor = expectedType[0];
        const currentType = tile.userData.type;
        const currentColor = currentType[0];

        if (expectedType.startsWith('T') || expectedType === '@@') {
            if (currentColor !== expectedColor) return false;
            continue;
        }

        // Allow creative placement for paths with endpoints
        if (pathColors.has(expectedColor)) continue;
        // Allow routing through empty spaces
        if (expectedColor === '*' && pathColors.has(currentColor)) continue;

        if (!isTileMatch(tile, rawExpectedType)) return false;
    }

    const mod = (n, m) => ((n % m) + m) % m;
    const directions = [[-1, 0], [0, -1], [1, -1], [1, 0], [0, 1], [-1, 1]];
    const getEffectiveEdge = (tile, p) => {
        if (p === 6) return 6;
        const r = tile.userData.rotation !== undefined ? tile.userData.rotation : 0;
        const f = tile.userData.flipped || false;
        return mod((f ? -p : p) + r, 6);
    };

    // Trace generic paths
    for (const color of pathColors) {
        const eps = endpointsByColor[color];
        if (!eps || eps.length !== 2) return false; // Ensure it is a strict pair

        const [ep1, ep2] = eps;
        const startTile = tiles.get(ep1.key);
        const endTile = tiles.get(ep2.key);
        if (!startTile || !endTile) return false;

        const visited = new Set();
        const tracePath = (currentTile, entryEdge) => {
            const tileKey = `${currentTile.userData.q},${currentTile.userData.r}`;
            if (visited.has(tileKey) || currentTile.userData.type[0] !== color) return false;
            visited.add(tileKey);
            
            if (currentTile === endTile) {
                if (entryEdge !== null) {
                    const pathEdges = currentTile.userData.pathEdges;
                    if (!pathEdges) {
                        visited.delete(tileKey);
                        return false;
                    }
                    for (const p of pathEdges) {
                        const e1 = getEffectiveEdge(currentTile, p[0]);
                        const e2 = getEffectiveEdge(currentTile, p[1]);
                        if (e1 === entryEdge || e2 === entryEdge) {
                            if (e1 === ep2.edge || e2 === ep2.edge) return true;
                        }
                    }
                    visited.delete(tileKey);
                    return false;
                }
                return true;
            }

            const pathEdges = currentTile.userData.pathEdges;
            if (!pathEdges) {
                visited.delete(tileKey);
                return false;
            }

            for (const p of pathEdges) {
                const e1 = getEffectiveEdge(currentTile, p[0]);
                const e2 = getEffectiveEdge(currentTile, p[1]);
                
                const attemptTraceFrom = (exitEdge) => {
                    if (exitEdge === 6) return false;
                    const [dq, dr] = directions[exitEdge];
                    const nextTile = tiles.get(`${currentTile.userData.q + dq},${currentTile.userData.r + dr}`);
                    if (nextTile) return tracePath(nextTile, mod(exitEdge + 3, 6));
                    return false;
                };

                if (entryEdge === null) {
                        if (e1 !== 6 && attemptTraceFrom(e1)) return true;
                        if (e2 !== 6 && attemptTraceFrom(e2)) return true;
                } else if (e1 === entryEdge && attemptTraceFrom(e2)) return true;
                else if (e2 === entryEdge && attemptTraceFrom(e1)) return true;
            }
                
                visited.delete(tileKey);
            return false;
        };

        if (!tracePath(startTile, null)) return false;
    }
    return true;
}

export function checkWinCondition() {
    if (!levelConfig || !levelConfig.objective) return;
    const obj = levelConfig.objective;

    if (obj.type === 'match_map' || obj.type === 'match_pieces') {
        const state = getObjectiveState();
        if (!state) return;
        
        let isWin = state.isWin;

        // Fallback for conceptual bug: If exact match fails, check if the paths form a valid logical connection!
        if (!isWin) {
            isWin = evaluateLogicalWin(state.objMap);
        }
        
        const newlyCompleted = [];
        if (isWin) {
            for (const z of state.sortedZones) {
                if (!completedZones.has(z)) {
                    newlyCompleted.push(z);
                    completedZones.add(z);
                }
            }
        } else {
            for (const z of state.sortedZones) {
                if (state.zonesState[z].matched && !completedZones.has(z)) {
                    newlyCompleted.push(z);
                    completedZones.add(z);
                }
            }
        }
        
        if (newlyCompleted.length > 0) {
            if (!levelConfig || !levelConfig.isTutorial) {
                console.log(`[Game] Zones ${newlyCompleted.join(', ')} complete!`);
            }
            playSFX('win'); // Plays when a zone completes!
            
            const zonesConfig = levelConfig?.zones || {};
            const flashMeshes = [];
            const flashMat = new THREE.MeshBasicMaterial({ color: 0xffffff, transparent: true, opacity: 0.8, blending: THREE.AdditiveBlending });

            // Beautiful Ice Shatter & Flash Animation
            tiles.forEach((tile, key) => {
                const z = state.hasZones ? (zonesConfig[key] !== undefined ? zonesConfig[key] : 0) : 1;

                if (tile.userData.freezeLevel > 0 && newlyCompleted.includes(tile.userData.freezeLevel) && tile.userData.iceMesh) {
                    const ice = tile.userData.iceMesh;
                    tile.userData.iceMesh = null; // Prevent overlapping triggers
                    setTileType(tile); // Instantly remove the 30% brightness boost
                    if (ice && ice.material) {
                        activeTweens.push((time) => {
                            if (!ice.userData.startTime) ice.userData.startTime = time;
                            const p = (time - ice.userData.startTime) / 500; // 500ms melt
                            if (p >= 1) { tile.remove(ice); return true; }
                            ice.scale.set(0.96 * (1 - p), 2.2 * (1 - p), 0.96 * (1 - p));
                            ice.material.opacity = 0.5 * (1 - p);
                            return false;
                        });
                    }
                }

                if (newlyCompleted.includes(z)) {
                    const flashMesh = new THREE.Mesh(hitboxGeometry, flashMat);
                    flashMesh.position.y = 0;
                    flashMesh.scale.set(1.02, 1.2, 1.02);
                    tile.add(flashMesh);
                    flashMeshes.push(flashMesh);
                }
            });

            activeTweens.push((time) => {
                if (!flashMat.userData.startTime) flashMat.userData.startTime = time;
                const p = (time - flashMat.userData.startTime) / 600; // 600ms flash
                if (p >= 1) {
                    flashMeshes.forEach(m => m.parent.remove(m));
                    flashMat.dispose();
                    return true;
                }
                flashMat.opacity = 0.8 * (1 - p);
                return false;
            });
        }

        if (isWin && !levelWon && !levelConfig.isTutorial) {
            levelWon = true;
            if (onWinCallback) onWinCallback();
        }
    } else if (obj.type === 'path_connect' && obj.targets) {
        const mod = (n, m) => ((n % m) + m) % m;
        const directions = [[-1, 0], [0, -1], [1, -1], [1, 0], [0, 1], [-1, 1]]; // q, r offsets for edges 0-5
        const getEffectiveEdge = (tile, p) => {
            if (p === 6) return 6; // Center endpoint
            const r = tile.userData.rotation !== undefined ? tile.userData.rotation : 0;
            const f = tile.userData.flipped || false;
            return mod((f ? -p : p) + r, 6);
        };
        const startCoords = obj.targets[0];
        const endCoords = obj.targets[1];
        const startTile = tiles.get(`${startCoords.q},${startCoords.r}`);
        const endTile = tiles.get(`${endCoords.q},${endCoords.r}`);

        if (!startTile || !endTile) return;

        const visited = new Set();
        let isWin = false;

        // Recursive path tracing function
        const tracePath = (currentTile, entryEdge) => {
            const tileKey = `${currentTile.userData.q},${currentTile.userData.r}`;
            if (visited.has(tileKey)) return false; // Loop detected
            visited.add(tileKey);

            // Check if we reached the end target
            if (currentTile === endTile) {
                // We need to make sure the path on the end tile actually connects to our entry edge.
                if (entryEdge !== null) {
                    const { pathEdges } = currentTile.userData;
                    if (!pathEdges) return false;
                    for (const path of pathEdges) {
                        const e1 = getEffectiveEdge(currentTile, path[0]);
                        const e2 = getEffectiveEdge(currentTile, path[1]);
                        if (e1 === entryEdge || e2 === entryEdge) return true; // Path connects to the end!
                    }
                    return false; // End tile reached, but path doesn't connect to entry
                }
                return true; // This case (start === end) should be handled by level design, but counts as a win.
            }

            const { pathEdges } = currentTile.userData;
            if (!pathEdges) return false; // Path broken

            // For the start tile, we can exit from any path end. For others, we must find the connecting path.
            for (const path of pathEdges) {
                const e1 = getEffectiveEdge(currentTile, path[0]);
                const e2 = getEffectiveEdge(currentTile, path[1]);
                
                const attemptTraceFrom = (exitEdge) => {
                    if (exitEdge === 6) return false; // Cannot exit through the center
                    const [dq, dr] = directions[exitEdge];
                    const nextTile = tiles.get(`${currentTile.userData.q + dq},${currentTile.userData.r + dr}`);
                    if (nextTile) {
                        return tracePath(nextTile, mod(exitEdge + 3, 6));
                    }
                    return false;
                };

                if (entryEdge === null) { // Start of the trace, can go either way
                    if (e1 !== 6 && attemptTraceFrom(e1)) return true;
                    if (e2 !== 6 && attemptTraceFrom(e2)) return true;
                } else if (e1 === entryEdge) {
                    if (attemptTraceFrom(e2)) return true;
                } else if (e2 === entryEdge) {
                    if (attemptTraceFrom(e1)) return true;
                }
            }
            
            visited.delete(tileKey);
            return false;
        };
        
        isWin = tracePath(startTile, null);

        if (isWin && !levelWon && !levelConfig.isTutorial) {
            levelWon = true;
            if (onWinCallback) onWinCallback();
        }
    }
}

export function flipTile(source, target) {
    if (!levelConfig || !levelConfig.isTutorial) {
        trackAction('flip', { source: `${source.userData.q},${source.userData.r}`, target: `${target.userData.q},${target.userData.r}` });
        console.log(`[Debug] Flipping tiles: (${source.userData.q}, ${source.userData.r}) <-> (${target.userData.q}, ${target.userData.r})`);
    }
    playSFX('flip');
    isAnimating = true;
    source.position.y = 0; // Drop the selected tile flush before flipping

    const sq = source.userData.q;
    const sr = source.userData.r;
    const tq = target.userData.q;
    const tr = target.userData.r;

    // Update logical grid
    tiles.set(`${tq},${tr}`, source);
    tiles.set(`${sq},${sr}`, target);
    
    source.userData.q = tq;
    source.userData.r = tr;
    target.userData.q = sq;
    target.userData.r = sr;

    const advanceColorIndex = (tile) => {
        if (!tile.userData.type.startsWith('**') && !tile.userData.type.startsWith('@@') && !tile.userData.type.startsWith('T')) {
            tile.userData.colorIndex = (tile.userData.colorIndex || 0) + 1;
        }
    };
    advanceColorIndex(source);
    advanceColorIndex(target);

    // --- Path Rotation Logic ---
    const neighborDirections = { '-1,0': 0, '0,-1': 1, '1,-1': 2, '1,0': 3, '0,1': 4, '-1,1': 5 };
    const flipDir = neighborDirections[`${tq-sq},${tr-sr}`];

    const mod = (n, m) => ((n % m) + m) % m;
    
    // Geometric State Updates
    const sourceR = source.userData.rotation !== undefined ? source.userData.rotation : 0;
    const sourceF = source.userData.flipped || false;
    const targetR = target.userData.rotation !== undefined ? target.userData.rotation : 0;
    const targetF = target.userData.flipped || false;

    // Visual reflection across Edge E perfectly maps to state:
    // new_flipped = !flipped, new_rotation = mod(2E + 3 - rotation, 6)
    source.userData.rotation = mod(2 * flipDir + 3 - sourceR, 6);
    source.userData.flipped = !sourceF;

    const targetFlipDir = (flipDir + 3) % 6;
    target.userData.rotation = mod(2 * targetFlipDir + 3 - targetR, 6);
    target.userData.flipped = !targetF;

    const oldPos = axialToWorld(sq, sr);
    const newPos = axialToWorld(tq, tr);

    // Calculate rotation axis and pivot
    const dx = newPos.x - oldPos.x;
    const dz = newPos.z - oldPos.z;
    const midX = oldPos.x + dx / 2;
    const midZ = oldPos.z + dz / 2;
    
    const len = Math.sqrt(dx*dx + dz*dz);
    const axis = new THREE.Vector3(-dz/len, 0, dx/len); // Perpendicular to movement

    const pivot = new THREE.Group();
    pivot.position.set(midX, 0, midZ);
    boardGroup.add(pivot);
    
    // Attach BOTH tiles for a synchronized physical flip
    pivot.attach(source);
    pivot.attach(target);

    const duration = 500; // ms (slightly longer for a weighty feel)
    const startTime = performance.now();

    activeTweens.push((time) => {
        let progress = (time - startTime) / duration;
        if (progress > 1) progress = 1;
        
        // Ease In Out Quadratic
        const ease = progress < 0.5 ? 2 * progress * progress : 1 - Math.pow(-2 * progress + 2, 2) / 2;
        
        // Rotate by -PI so the tiles flip UPwards over the board
        pivot.setRotationFromAxisAngle(axis, -Math.PI * ease);
        
        if (progress === 1) {
            boardGroup.attach(source);
            boardGroup.attach(target);
            boardGroup.remove(pivot);
            
            // Snap to exact mathematical positions to prevent drift
            source.position.set(newPos.x, 0, newPos.z);
            target.position.set(oldPos.x, 0, oldPos.z);
            
            // Apply the new materials now that the flip is complete
            setTileType(source);
            setTileType(target);
            
            stepCount++;
            const stepDisplay = document.getElementById('step-count-display');
            if (stepDisplay) {
                stepDisplay.innerText = `Steps: ${stepCount}`;
            }

            isAnimating = false;
            checkWinCondition(); // Check win state after flip
            return true; // Removes tween
        }
        return false;
    });
}

export function performSingleFlip(tile) {
    if (!levelConfig || !levelConfig.isTutorial) {
        trackAction('single_flip', { target: `${tile.userData.q},${tile.userData.r}` });
    }
    playSFX('flip');
    isAnimating = true;
    tile.position.y = 0; // Drop the selected tile flush before flipping

    if (!tile.userData.type.startsWith('**') && !tile.userData.type.startsWith('@@') && !tile.userData.type.startsWith('T')) {
        tile.userData.colorIndex = (tile.userData.colorIndex || 0) + 1;
    }

    // For an in-place physical flip over the X-axis, the rotation negates
    const oldR = tile.userData.rotation !== undefined ? tile.userData.rotation : 0;
    const mod = (n, m) => ((n % m) + m) % m;
    tile.userData.rotation = mod(-oldR, 6);
    tile.userData.flipped = !(tile.userData.flipped || false);

    const pivot = new THREE.Group();
    pivot.position.copy(tile.position);
    boardGroup.add(pivot);
    pivot.attach(tile);

    const axis = new THREE.Vector3(1, 0, 0); // X-axis
    const duration = 500;
    const startTime = performance.now();

    activeTweens.push((time) => {
        let progress = (time - startTime) / duration;
        if (progress > 1) progress = 1;
        
        const ease = progress < 0.5 ? 2 * progress * progress : 1 - Math.pow(-2 * progress + 2, 2) / 2;
        
        pivot.setRotationFromAxisAngle(axis, -Math.PI * ease);
        pivot.position.y = Math.sin(ease * Math.PI) * 0.8; // Lift up gracefully during the flip
        
        if (progress === 1) {
            boardGroup.attach(tile);
            boardGroup.remove(pivot);
            tile.position.y = 0; // Ensure perfectly flush
            
            setTileType(tile);
            
            stepCount++;
            const stepDisplay = document.getElementById('step-count-display');
            if (stepDisplay) {
                stepDisplay.innerText = `Steps: ${stepCount}`;
            }

            isAnimating = false;
            checkWinCondition(); // Check win state after flip
            return true; // Removes tween
        }
        return false;
    });
}

export function performSingleRotate(tile) {
    if (!levelConfig || !levelConfig.isTutorial) {
        trackAction('single_rotate', { target: `${tile.userData.q},${tile.userData.r}` });
    }
    playSFX('flip');
    isAnimating = true;
    tile.position.y = 0; // Drop the selected tile flush before rotating

    const oldR = tile.userData.rotation !== undefined ? tile.userData.rotation : 0;
    const mod = (n, m) => ((n % m) + m) % m;
    tile.userData.rotation = mod(oldR + 1, 6);

    const pivot = new THREE.Group();
    pivot.position.copy(tile.position);
    boardGroup.add(pivot);
    pivot.attach(tile);

    const axis = new THREE.Vector3(0, 1, 0); // Y-axis
    const duration = 400;
    const startTime = performance.now();

    activeTweens.push((time) => {
        let progress = (time - startTime) / duration;
        if (progress > 1) progress = 1;
        
        const ease = progress < 0.5 ? 2 * progress * progress : 1 - Math.pow(-2 * progress + 2, 2) / 2;
        
        pivot.setRotationFromAxisAngle(axis, -Math.PI / 3 * ease);
        pivot.position.y = Math.sin(ease * Math.PI) * 0.4; // Lift up gracefully during the rotate
        
        if (progress === 1) {
            boardGroup.attach(tile);
            boardGroup.remove(pivot);
            tile.position.y = 0; // Ensure perfectly flush
            
            stepCount++;
            const stepDisplay = document.getElementById('step-count-display');
            if (stepDisplay) {
                stepDisplay.innerText = `Steps: ${stepCount}`;
            }

            isAnimating = false;
            checkWinCondition(); // Check win state after rotate
            return true; // Removes tween
        }
        return false;
    });
}

const raycaster = new THREE.Raycaster();
const mouse = new THREE.Vector2();

function getIntersectedObject(event) {
    let clientX = event.clientX;
    let clientY = event.clientY;
    
    if (event.touches && event.touches.length > 0) {
        clientX = event.touches[0].clientX;
        clientY = event.touches[0].clientY;
    }

    mouse.x = (clientX / window.innerWidth) * 2 - 1;
    mouse.y = -(clientY / window.innerHeight) * 2 + 1;

    raycaster.setFromCamera(mouse, camera);
    // Intersect with the precise, non-overlapping hitboxes instead of the visual meshes
    const intersects = raycaster.intersectObjects(hitboxes);

    if (intersects.length > 0) {
        // The intersection object's `object` property is the hitbox mesh.
        // We stored a reference to the main tile group in its userData.
        const tileGroup = intersects[0].object.userData.tileGroup;
        // Return the intersection data, but replace the object with the tile group
        return { ...intersects[0], object: tileGroup };
    }
    console.log("[Debug] Raycast missed all hitboxes.");
    return null;
}

export function onPointerDown(event) {
    if (currentState !== GameState.PLAYING) return;
    
    if (isHintActive) {
        trackAction('hint_dismiss', { method: 'board_tap' });
        clearHints();
        return; // Consume the tap to just dismiss the hint
    }

    if (isAnimating) return;
    isPointerDown = true;

    if (isSingleFlipActive) {
        const hit = getIntersectedObject(event);
        if (!hit) {
            toggleSingleFlipMode(); // Cancel tool if missed
            return;
        }
        const clickedHex = hit.object;
        if (clickedHex.userData.q !== undefined && !isFixedTile(clickedHex)) {
            performSingleFlip(clickedHex);
            toggleSingleFlipMode();
            if (onSingleFlipConsumed) onSingleFlipConsumed();
        } else {
            toggleSingleFlipMode(); // Cancel tool if unmovable block clicked
        }
        isPointerDown = false;
        return;
    }

    if (isSingleRotateActive) {
        const hit = getIntersectedObject(event);
        if (!hit) {
            toggleSingleRotateMode(); // Cancel tool if missed
            return;
        }
        const clickedHex = hit.object;
        if (clickedHex.userData.q !== undefined && !isFixedTile(clickedHex)) {
            performSingleRotate(clickedHex);
            toggleSingleRotateMode();
            if (onSingleRotateConsumed) onSingleRotateConsumed();
        } else {
            toggleSingleRotateMode(); // Cancel tool if unmovable block clicked
        }
        isPointerDown = false;
        return;
    }

    const hit = getIntersectedObject(event);
    if (!hit) {
        if (selectedTile) {
            selectedTile.position.y = 0;
            selectedTile = null;
        }
        return;
    }

    const clickedHex = hit.object; // This is now the tile's main group
    if (clickedHex.userData.q === undefined || isFixedTile(clickedHex)) return;

    console.log(`\n[Debug] --- Click Started ---`);
    console.log(`[Debug] Hit Point (World):`, hit.point);
    console.log(`[Debug] Tile Data -> q: ${clickedHex.userData.q}, r: ${clickedHex.userData.r}, type: ${clickedHex.userData.type}`);

    // Convert world hit point to boardGroup's local space to match tile positions
    const localPoint = boardGroup.worldToLocal(hit.point.clone());
    const center = clickedHex.position;
    const dx = localPoint.x - center.x;
    const dz = localPoint.z - center.z;
    const distFromCenter = Math.sqrt(dx*dx + dz*dz);
    
    console.log(`[Debug] Local Point:`, localPoint, `| Dist from center:`, distFromCenter);

    // 1. Check Edge Click (outer 40% of the tile)
    if (distFromCenter > 0.6) {
        let closestNeighbor = null;
        let minDistance = Infinity;
        const neighbors = [[1, 0], [1, -1], [0, -1], [-1, 0], [-1, 1], [0, 1]];
        
        neighbors.forEach(n => {
            const nTile = tiles.get(`${clickedHex.userData.q + n[0]},${clickedHex.userData.r + n[1]}`);
            if (nTile && !isFixedTile(nTile)) {
                const nCenter = nTile.position;
                const distToN = Math.sqrt(Math.pow(localPoint.x - nCenter.x, 2) + Math.pow(localPoint.z - nCenter.z, 2));
                console.log(`[Debug] Checking neighbor [${clickedHex.userData.q + n[0]}, ${clickedHex.userData.r + n[1]}] -> Dist to N:`, distToN);
                if (distToN < minDistance) {
                    minDistance = distToN;
                    closestNeighbor = nTile;
                }
            }
        });
        
        console.log(`[Debug] Closest neighbor:`, closestNeighbor ? `(${closestNeighbor.userData.q}, ${closestNeighbor.userData.r}) with dist: ${minDistance}` : "None found");

        if (closestNeighbor) {
            if (isBlockedEdge(clickedHex, closestNeighbor)) {
                isPointerDown = false;
                return;
            }
            if (selectedTile) { selectedTile.position.y = 0; selectedTile = null; }
            flipTile(clickedHex, closestNeighbor);
            isPointerDown = false; // consume input
            return;
        }
    }

    // 2. Center Click / Selection Logic
    if (selectedTile && selectedTile !== clickedHex) {
        if (isHexAdjacent(selectedTile.userData.q, selectedTile.userData.r, clickedHex.userData.q, clickedHex.userData.r)) {
            if (isBlockedEdge(selectedTile, clickedHex)) {
                selectedTile.position.y = 0;
                selectedTile = clickedHex;
                selectedTile.position.y = 0.2;
            } else {
                flipTile(selectedTile, clickedHex);
                selectedTile = null;
                isPointerDown = false;
                return;
            }
        } else {
            selectedTile.position.y = 0;
            selectedTile = clickedHex;
            selectedTile.position.y = 0.2;
        }
    } else if (!selectedTile) {
        selectedTile = clickedHex;
        selectedTile.position.y = 0.2;
    }
    
    dragStartTile = clickedHex;
}

export function onPointerMove(event) {
    if (currentState !== GameState.PLAYING) return;

    if (!isPointerDown || isAnimating || !dragStartTile) return;
    
    const hit = getIntersectedObject(event);
    if (!hit) return;
    
    const hoveredHex = hit.object; // This is now the tile's main group
    if (hoveredHex.userData.q === undefined || isFixedTile(hoveredHex)) return;
    
    if (hoveredHex !== dragStartTile && isHexAdjacent(dragStartTile.userData.q, dragStartTile.userData.r, hoveredHex.userData.q, hoveredHex.userData.r)) {
        if (isBlockedEdge(dragStartTile, hoveredHex)) return;
        if (selectedTile) { selectedTile.position.y = 0; selectedTile = null; }
        flipTile(dragStartTile, hoveredHex);
        dragStartTile = null;
        isPointerDown = false;
    }
}

export function onPointerUp(event) {
    isPointerDown = false;
    dragStartTile = null;
}