export function initLogger() {
    const originalLog = console.log;
    const originalWarn = console.warn;
    const originalError = console.error;
    const originalDebug = console.debug;

    // Override the global console methods
    console.log = (...args) => {
        originalLog(...args);
        // Future custom native logcat/crashlytics integration goes here!
        // Example: NativeLogger.log({ level: 'info', message: JSON.stringify(args) });
    };

    console.warn = (...args) => {
        originalWarn(...args);
    };

    console.error = (...args) => {
        originalError(...args);
    };

    console.debug = (...args) => {
        originalDebug(...args);
    };
}