// Camera viewing settings
const CAMERA_ANGLE_FROM_TOP_DEGREES = 15; // Angle from being directly top-down. 0 = top-down, 90 = side-on.
const CAMERA_DISTANCE_MULTIPLIER = 0.8; // Decrease this value to bring the camera closer. 1.0 = tight fit.

export const scene = new THREE.Scene();

let _bgResolve;
export const backgroundLoaded = new Promise(resolve => _bgResolve = resolve);

const bgTexture = new THREE.TextureLoader().load(
    'background.webp', 
    () => {
        // Trigger a resize update once the image loads to ensure it scales correctly immediately
        window.dispatchEvent(new Event('resize'));
        _bgResolve();
    },
    undefined,
    () => _bgResolve() // Resolve anyway on error so the game doesn't freeze
);
bgTexture.colorSpace = THREE.SRGBColorSpace; // Ensures the image colors don't look washed out
scene.background = bgTexture;

export const boardGroup = new THREE.Group();
scene.add(boardGroup);

export function updateCameraFrustum(cam, width, height) {
    const aspect = width / height;
    cam.aspect = aspect;
    
    // Update background stretch/squeeze to maintain aspect ratio with up to 10% distortion
    if (bgTexture.image) {
        const imageAspect = bgTexture.image.width / bgTexture.image.height;
        const maxStretch = 1.1; // 10% stretch/squeeze tolerance
        
        let targetAspect = aspect;
        if (targetAspect > imageAspect * maxStretch) {
            targetAspect = imageAspect * maxStretch;
        } else if (targetAspect < imageAspect / maxStretch) {
            targetAspect = imageAspect / maxStretch;
        }
        
        let ux = 1, uy = 1;
        if (aspect > targetAspect) {
            uy = targetAspect / aspect; // Screen is wider, crop top/bottom
        } else {
            ux = aspect / targetAspect; // Screen is taller, crop left/right
        }
        
        bgTexture.repeat.set(ux, uy);
        bgTexture.offset.set((1 - ux) / 2, (1 - uy) / 2);
    }
    
    if (boardGroup.children.length > 0) {
        // Temporarily hide shadow mesh so it doesn't artificially expand the camera zoom bounds
        const shadowMesh = boardGroup.userData.shadowMesh;
        if (shadowMesh) shadowMesh.visible = false;

        boardGroup.updateMatrixWorld(true);
        const box = new THREE.Box3().setFromObject(boardGroup);
        const size = box.getSize(new THREE.Vector3());
        const center = box.getCenter(new THREE.Vector3());

        if (shadowMesh) shadowMesh.visible = true;

        // Calculate the required distance (height) to fit the board in the view.
        // Based on the camera's FOV and the larger dimension of the board.
        const fovRad = THREE.MathUtils.degToRad(cam.fov);
        
        // If the screen is in portrait mode, we rotate the camera by 90 degrees
        // so the board's width (X) aligns with the screen's height (Y) to maximize size.
        const isPortrait = aspect < 1;
        
        // Define UI reserved areas (18% top, 16% bottom)
        const topMargin = 0.18;
        const bottomMargin = 0.16;
        const usableHeightFactor = 1.0 - topMargin - bottomMargin;
        const centerShift = topMargin + usableHeightFactor / 2.0 - 0.5; // Shift amount to center in the usable sub-region
        
        let distForWidth, distForHeight;
        if (isPortrait) {
            // Camera looks from the side (+X), so screen width fits board Z, screen height fits board X
            distForWidth = (size.z / 2) / (aspect * Math.tan(fovRad / 2));
            distForHeight = (size.x / 2) / (Math.tan(fovRad / 2) * usableHeightFactor);
        } else {
            // Camera looks from the front (+Z), so screen width fits board X, screen height fits board Z
            distForWidth = (size.x / 2) / (aspect * Math.tan(fovRad / 2));
            distForHeight = (size.z / 2) / (Math.tan(fovRad / 2) * usableHeightFactor);
        }
        
        let distance = Math.max(distForWidth, distForHeight) * CAMERA_DISTANCE_MULTIPLIER;

        // Position camera based on the desired viewing angle
        const angleFromTopRad = THREE.MathUtils.degToRad(CAMERA_ANGLE_FROM_TOP_DEGREES);
        const offset = distance * Math.tan(angleFromTopRad);
        const camY = center.y + distance;

        if (isPortrait) {
            cam.up.set(-1, 0, 0); // Fix gimbal lock, align top of screen to -X
            cam.position.set(center.x + offset, camY, center.z);
        } else {
            cam.up.set(0, 0, -1); // Fix gimbal lock, align top of screen to -Z
            cam.position.set(center.x, camY, center.z + offset);
        }
        cam.lookAt(center);
        
        // Shift camera to perfectly center the board in the usable screen area
        const trueDistance = cam.position.distanceTo(center);
        const frustumHeight = 2 * trueDistance * Math.tan(fovRad / 2);
        cam.translateY(centerShift * frustumHeight);
    }

    cam.updateProjectionMatrix();
}

// 2.5D Camera Setup (Angled perspective, straight on)
// export const camera = new THREE.OrthographicCamera(-1, 1, 1, -1, 1, 1000);
export const camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
camera.position.set(0, 10, 5); // Initial position before first level load
camera.lookAt(scene.position);

export const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });
renderer.setSize(window.innerWidth, window.innerHeight);
document.body.appendChild(renderer.domElement);

// Lighting
const ambientLight = new THREE.AmbientLight(0xffffff, 0.6);
scene.add(ambientLight);
const dirLight = new THREE.DirectionalLight(0xffffff, 0.8);
dirLight.position.set(10, 20, 10);
scene.add(dirLight);