// Load saved volumes or default to 50%
let bgmVolume = 0.5;
let sfxVolume = 0.5;

const sounds = {
    bgm: new Audio('audio/bgm.mp3'),
    flip: new Audio('audio/flip.mp3'),
    win: new Audio('audio/win.mp3'),
};

sounds.bgm.loop = true;
sounds.bgm.volume = bgmVolume;

let initialized = false;

export function initAudio() {
    if (initialized) return;
    // Browsers block autoplay; this must be called as a direct result of a user click
    sounds.bgm.play().catch(() => console.log("[Audio] Autoplay blocked."));
    initialized = true;
}

export function playSFX(name) {
    if (!sounds[name]) return;
    const sfx = sounds[name].cloneNode(); // Clone allows overlapping sounds (e.g. fast flipping)
    sfx.volume = sfxVolume;
    sfx.play().catch(e => console.log("[Audio] Failed to play SFX:", e));
}

export function setBGMVolume(vol) {
    bgmVolume = vol;
    sounds.bgm.volume = bgmVolume;
}

export function setSFXVolume(vol) {
    sfxVolume = vol;
}

export function getVolumes() { return { bgmVolume, sfxVolume }; }