import { saveData, loadData } from './platform.js';

const SAVE_GAME_KEY = 'symmetry6-save-data';

// This function simulates signing into a service like Google Play Games.
// In a real app, this would involve the GPGS SDK and OAuth.
export async function initProgressService() {
    console.log("[Progress] Initializing save game service...");
    await new Promise(resolve => setTimeout(resolve, 200)); // Simulate SDK load
    console.log("[Progress] Service ready.");
    return true;
}

// This simulates saving a snapshot to the cloud.
export async function saveProgress(progress) {
    console.log("[Progress] Saving to cloud:", progress);
    try {
        const dataToSave = {
            currentLevelIndex: progress.currentLevelIndex,
            maxUnlockedLevel: progress.maxUnlockedLevel !== undefined ? progress.maxUnlockedLevel : progress.currentLevelIndex,
            currentPuzzleIndex: progress.currentPuzzleIndex,
            unlockedPieces: Array.from(progress.unlockedPieces), // Convert Set to Array for JSON
            levelStars: progress.levelStars || {},
            hintsAvailable: progress.hintsAvailable || 0,
            flipsAvailable: progress.flipsAvailable || 0,
            rotatesAvailable: progress.rotatesAvailable || 0,
            coins: progress.coins || 0,
            lastDailyClaim: progress.lastDailyClaim || 0,
            adFreeUntil: progress.adFreeUntil || 0,
            audio: progress.audio || { bgmVolume: 0.5, sfxVolume: 0.5 }
        };
        await saveData(SAVE_GAME_KEY, dataToSave);
        console.log("[Progress] Save successful.");
        return { success: true };
    } catch (error) {
        console.error("[Progress] Failed to save progress:", error);
        return { success: false, error };
    }
}

// This simulates loading a snapshot from the cloud.
export async function loadProgress() {
    console.log("[Progress] Loading from cloud...");
    try {
        const savedData = await loadData(SAVE_GAME_KEY);

        if (savedData) {
            // Convert array back to Set
            savedData.unlockedPieces = new Set(savedData.unlockedPieces);
            if (savedData.maxUnlockedLevel === undefined) {
                savedData.maxUnlockedLevel = savedData.currentLevelIndex || 0;
            }
            console.log("[Progress] Loaded data:", savedData);
            return savedData;
        } else {
            // Return a default state for a new player
            console.log("[Progress] No save data found. Starting new game.");
            return { currentLevelIndex: 0, maxUnlockedLevel: 0, currentPuzzleIndex: 0, unlockedPieces: new Set(), levelStars: {}, hintsAvailable: 0, flipsAvailable: 0, rotatesAvailable: 0, coins: 0, lastDailyClaim: 0, adFreeUntil: 0, audio: { bgmVolume: 0.5, sfxVolume: 0.5 } };
        }
    } catch (error) {
        console.error("[Progress] Failed to load progress:", error);
        // Return default state on error to prevent game from breaking
        return { currentLevelIndex: 0, maxUnlockedLevel: 0, currentPuzzleIndex: 0, unlockedPieces: new Set(), levelStars: {}, hintsAvailable: 0, flipsAvailable: 0, rotatesAvailable: 0, coins: 0, lastDailyClaim: 0, adFreeUntil: 0, audio: { bgmVolume: 0.5, sfxVolume: 0.5 } };
    }
}