// --- Hexagon Math (Pointy-topped) ---
export const hexRadius = 1;
export const hexHeight = 0.1; // Total thickness (0.05 top mesh + 0.05 bottom mesh)

const simpleHexShape = new THREE.Shape();
for (let i = 0; i < 6; i++) {
    const a = (i / 6) * Math.PI * 2;
    const x = Math.sin(a) * hexRadius;
    const y = Math.cos(a) * hexRadius;
    if (i === 0) {
        simpleHexShape.moveTo(x, y);
    } else {
        simpleHexShape.lineTo(x, y);
    }
}
export const hitboxGeometry = new THREE.ExtrudeGeometry(simpleHexShape, { depth: hexHeight, bevelEnabled: false });
hitboxGeometry.center();
hitboxGeometry.rotateX(Math.PI / 2); // Lay flat on the board

// Remap UVs for the top and bottom faces of the hexagon to be in the 0-1 range,
// which is what most textures expect. The default ExtrudeGeometry UVs are based
// on the shape's vertex coordinates, which for a unit hexagon are in the -1 to 1 range.
const positions = hitboxGeometry.attributes.position;
const uvs = hitboxGeometry.attributes.uv;
const yThreshold = hexHeight / 2 * 0.99; // A threshold to reliably identify cap vertices

for (let i = 0; i < positions.count; i++) {
    if (Math.abs(positions.getY(i)) >= yThreshold) { // It's a cap vertex
        uvs.setXY(i, uvs.getX(i) * 0.5 + 0.5, uvs.getY(i) * 0.5 + 0.5);
    }
}
uvs.needsUpdate = true;
// hitboxGeometry.scale(1.04, 1, 1.04); // Match the scale of the visual tiles

