/**
 * Asynchronously loads the master hexagon geometries from OBJ files.
 * This must be called and awaited before any level building begins.
 */
export function loadGeometries(onProgress) {
    const gltfLoader = new THREE.GLTFLoader();

    // Configure Draco loader to decode compressed meshes
    const dracoLoader = new THREE.DRACOLoader();
    dracoLoader.setDecoderPath('https://www.gstatic.com/draco/v1/decoders/');
    gltfLoader.setDRACOLoader(dracoLoader);

    const mtlLoader = new THREE.MTLLoader();
    const objLoader = new THREE.OBJLoader();
    
    const processLoadedGroup = (group, baseName) => {
        if (!group) return null;
        let hasMesh = false;
        group.traverse((child) => { if (child.isMesh) hasMesh = true; });
        if (!hasMesh) return null;

        const box = new THREE.Box3().setFromObject(group);
        const center = box.getCenter(new THREE.Vector3());
        
        group.traverse((child) => {
            if (child.isMesh) {
                console.log(`[Model Loader] Tile Model: ${baseName}, Mesh Name: ${child.name}, Materials:`, child.material);
                child.geometry.translate(-center.x, 0, -center.z);
                
                const processMat = (mat) => {
                    if (mat && mat.name && mat.name.toLowerCase() === 'path') {
                        console.log(`[Model Loader] returning 'pathMat' for ${baseName} mesh ${child.name}`);
                        return pathMat;
                    }
                    return new THREE.MeshStandardMaterial({
                        color: 0xffffff,
                        map: fallbackTexture,
                        roughness: 0.8
                    });
                };

                if (Array.isArray(child.material)) {
                    child.material = child.material.map(processMat);
                } else {
                    child.material = processMat(child.material);
                }
            }
        });
        group.scale.set(1.04, 1, 1.04); 
        return group;
    };

    const loadModel = (baseName) => new Promise((resolve) => {
        // 1. Try GLB
        gltfLoader.load(
            `models/${baseName}.glb`,
            (gltf) => {
                console.log(`Loaded ${baseName}.glb`);
                resolve(processLoadedGroup(gltf.scene, baseName));
            },
            undefined,
            (e) => { // 2. Fallback to OBJ
                console.log(`Could not load ${baseName}.glb, falling back to .obj`);
                mtlLoader.load(
                    `models/${baseName}.mtl`,
                    (materials) => {
                        materials.preload();
                        objLoader.setMaterials(materials);
                        objLoader.load(`models/${baseName}.obj`, (group) => resolve(processLoadedGroup(group, baseName)), undefined, () => resolve(null));
                    },
                    undefined,
                    () => { // 3. Fallback to OBJ without MTL
                        objLoader.setMaterials(null);
                        objLoader.load(`models/${baseName}.obj`, (group) => resolve(processLoadedGroup(group, baseName)), undefined, () => resolve(null));
                    }
                );
            }
        );
    });

    const keys = Object.keys(modelLibrary);
    let loadedCount = 0;
    return Promise.all(keys.map(k => loadModel(k).then(res => {
        loadedCount++;
        if (onProgress) onProgress(loadedCount, keys.length);
        return res;
    }))).then(results => {
        keys.forEach((k, i) => {
            modelLibrary[k] = results[i];
        });
        console.log("Model loading process complete.");
    });
}

