export function setupProjectedMaterial(mat) {
    if (mat.userData.projectedSetup) return;
    mat.userData.projectedSetup = true;

    // Eagerly set uniform references so game logic can configure them immediately
    mat.userData.shaderUniforms = {
        projectedMap: { value: null },
        projectionScale: sharedProjectionUniforms.projectionScale,
        useProjectedMap: { value: 0.0 },
        uBrightness: { value: 1.0 },
        uBaseBoost: { value: 3.5 }
    };

    mat.onBeforeCompile = (shader) => {
        shader.uniforms.projectedMap = mat.userData.shaderUniforms.projectedMap;
        shader.uniforms.projectionScale = mat.userData.shaderUniforms.projectionScale;
        shader.uniforms.useProjectedMap = mat.userData.shaderUniforms.useProjectedMap;
        shader.uniforms.uBrightness = mat.userData.shaderUniforms.uBrightness;
        shader.uniforms.uBaseBoost = mat.userData.shaderUniforms.uBaseBoost;

        shader.vertexShader = `
            uniform float projectionScale;
            varying vec2 vTileUV;
            ${shader.vertexShader}
        `.replace(
            '#include <project_vertex>',
            `#include <project_vertex>
            vec4 worldPos = modelMatrix * vec4(position, 1.0);
            vec4 centerPos = modelMatrix * vec4(0.0, 0.0, 0.0, 1.0);
            // Calculate upright UV relative to the tile's absolute center in world space
            vec2 localPos = worldPos.xz - centerPos.xz;
            // Rotate UV -90 degrees (180 degrees from previous) with uniform scaling to prevent distortion
            vTileUV = vec2(localPos.y, -localPos.x) / projectionScale + 0.5;`
        );

        shader.fragmentShader = `
            uniform sampler2D projectedMap;
            uniform float useProjectedMap;
            uniform float uBrightness;
            uniform float uBaseBoost;
            varying vec2 vTileUV;
            ${shader.fragmentShader}
        `.replace(
            '#include <map_fragment>',
            `
            #include <map_fragment>
            
            if (useProjectedMap > 0.5) {
                vec4 symbolColor = texture2D(projectedMap, vTileUV);
                diffuseColor = symbolColor;
                diffuseColor.rgb *= uBrightness;
            } else {
                // Universally compensate for the darkening of the gray.webp base texture.
                // This restores the bright, vibrant hex colors of the base tiles.
                diffuseColor.rgb *= uBaseBoost;
            }
            `
        );
    };
}

export function getPathModelData(pathType) {
    const step = -Math.PI / 3; // CW rotation adds +1 to edge index mapping
    switch(pathType) {
        case 's': return { model: modelLibrary.tile_1line, rot: 0 };
        case 'c': return { model: modelLibrary.tile_1corner, rot: -step };
        case 'a': return { model: modelLibrary.tile_1arc, rot: 0 };
        case 'C': return { model: modelLibrary.tile_2corners_a, rot: -step };
        case 'B': return { model: modelLibrary.tile_2corners_b, rot: -step };
        case 't': return { model: modelLibrary.tile_3corners, rot: -step };
        case 'A': return { model: modelLibrary.tile_2arcs, rot: 0 };
        case '0': return { model: modelLibrary.tile_endpoint, rot: step };
        case '1': return { model: modelLibrary.tile_endpoint, rot: 2 * step };
        case '2': return { model: modelLibrary.tile_endpoint, rot: 3 * step };
        case '3': return { model: modelLibrary.tile_endpoint, rot: 4 * step };
        case '4': return { model: modelLibrary.tile_endpoint, rot: 5 * step };
        case '5': return { model: modelLibrary.tile_endpoint, rot: 6 * step };
        default: return { model: null, rot: 0 };
    }
}

export function getTileStyle(type, isTop) {
    if (!type || type === '**') return { color: '#838383', emissive: false, colorKey: '*' };
    const colorType = type.substring(0, 2);
    if (colorType === '@@') return { color: '#272727', emissive: false, colorKey: '@' };
    
    let colorKey = null;
    let isEmissive = false;
    
    if (colorType[0] === 'T') {
        colorKey = colorType[1];
        isEmissive = isTop; // Only the top of the target is emissive
    } else {
        colorKey = isTop ? colorType[0] : colorType[1];
    }

    const hex = colorHexes[colorKey] || '#ffffff';
    return { color: hex, emissive: isEmissive, colorKey: colorKey };
};

export function createPathMesh(pathEdges, isEndpoint = false) {
    const group = new THREE.Group();
    const pathWidth = 0.12; // Wider for a better visual presence
    const shapeRadius = hexRadius * 0.95; // Fit inside the bevel

    // Get the 3D positions of the midpoints of the hex's outer edges
    const edgeMidpoints = [];
    for (let i = 0; i < 6; i++) {
        const mappedIdx = (10 - i) % 6;
        const angle = (mappedIdx + 0.5) * (Math.PI / 3);
        const innerRadius = shapeRadius * Math.sqrt(3) / 2;
        edgeMidpoints.push(new THREE.Vector3(Math.sin(angle) * innerRadius, 0, Math.cos(angle) * innerRadius));
    }
    edgeMidpoints.push(new THREE.Vector3(0, 0, 0)); // Index 6 is the precise center

    pathEdges.forEach(path => {
        const p1 = edgeMidpoints[path[0]];
        const p2 = edgeMidpoints[path[1]];
        
        let curve;
        if (path[0] === 6 || path[1] === 6) {
            // Straight line for endpoints meeting at the center
            curve = new THREE.LineCurve3(p1, p2);
        } else {
            // Use a Cubic Bezier to ensure the path is perpendicular to the edges 
            // and curves smoothly towards the center without crossing it.
            const c1 = p1.clone().multiplyScalar(0.5);
            const c2 = p2.clone().multiplyScalar(0.5);
            curve = new THREE.CubicBezierCurve3(p1, c1, c2, p2);
        }
        
        const tubeGeom = new THREE.TubeGeometry(curve, 20, pathWidth, 8, false);
        const mesh = new THREE.Mesh(tubeGeom, isEndpoint ? pathEndpointMat : pathMat);
        mesh.scale.set(1, 0.2, 1); // Flatten the tube vertically to create a path ribbon
        group.add(mesh);
    });
    
    if (isEndpoint) {
        const hubGeom = new THREE.CylinderGeometry(0.2, 0.2, 0.06, 6);
        const hub = new THREE.Mesh(hubGeom, pathEndpointMat);
        group.add(hub);
    }

    return group;
}

export function axialToWorld(q, r) {
    const x = hexRadius * Math.sqrt(3) * (q + r/2);
    const z = hexRadius * 3/2 * r;
    return { x, z };
}

export function isHexAdjacent(q1, r1, q2, r2) {
    const dq = q1 - q2;
    const dr = r1 - r2;
    const neighbors = [[1, 0], [1, -1], [0, -1], [-1, 0], [-1, 1], [0, 1]];
    return neighbors.some(n => n[0] === dq && n[1] === dr);
}