let currentLevelIndex = -1;
let levelStartTime = 0;
let actionLog = [];
let gameVersion = 'unknown';

// Replace this with your Google Apps Script Web App URL or Firebase Cloud Function endpoint
const ANALYTICS_ENDPOINT = 'https://script.google.com/macros/s/AKfycbxUAscfy-MaG0PkaocxO-LEn7e_6fQBNTmzwGumIlOXhmB8PpmdQ3UkfFYhei7DuBL2/exec';
export function initAnalytics() {
    // Pre-initialize the user ID so it's ready for the first event
    getUserId();
}

export function setGameVersion(version) {
    gameVersion = version;
}

export function trackLevelStart(levelIndex) {
    currentLevelIndex = levelIndex;
    levelStartTime = Date.now();
    actionLog = [];
    sendEvent('level_start', { level: levelIndex });
}

export function trackAction(actionType, details) {
    if (currentLevelIndex === -1) return;
    const timeOffset = Date.now() - levelStartTime;
    const actionData = { time: timeOffset, action: actionType, ...details };
    actionLog.push(actionData);
    sendEvent('action', { level: currentLevelIndex, ...actionData });
}

export function trackLevelComplete(levelIndex, steps, timeElapsed) {
    const duration = Date.now() - levelStartTime;
    sendEvent('level_complete', {
        level: levelIndex,
        durationMs: duration,
        timeElapsedSec: timeElapsed,
        steps: steps,
        recording: actionLog
    });
    currentLevelIndex = -1; // Stop tracking actions until the next level starts
}

export function trackLevelRestart(levelIndex) {
    const duration = Date.now() - levelStartTime;
    sendEvent('level_restart', {
        level: levelIndex,
        durationMs: duration,
        recording: actionLog
    });
}

window.addEventListener('beforeunload', () => {
    // Safety net: Capture if the user closes the tab mid-level
    if (currentLevelIndex !== -1) {
        const duration = Date.now() - levelStartTime;
        sendEvent('level_abandoned', {
            level: currentLevelIndex,
            durationMs: duration,
            recording: actionLog
        });
    }
});

function getUserId() {
    let uid = localStorage.getItem('analytics_user_id');
    if (!uid) {
        uid = 'user_' + Math.random().toString(36).substring(2, 15) + Date.now().toString(36);
        localStorage.setItem('analytics_user_id', uid);
    }
    return uid;
}

function sendEvent(eventName, payload) {
    console.log(`[Analytics] ${eventName}:`, payload);

    // 1. Send telemetry to your custom backend
    if (ANALYTICS_ENDPOINT) {
        fetch(ANALYTICS_ENDPOINT, {
            method: 'POST',
            headers: { 'Content-Type': 'text/plain;charset=utf-8' },
            body: JSON.stringify({
                userId: getUserId(),
                version: gameVersion,
                event: eventName,
                payload: payload,
                timestamp: new Date().toISOString(),
                device: {
                    viewportWidth: window.innerWidth,
                    viewportHeight: window.innerHeight,
                    screenWidth: window.screen.width,
                    screenHeight: window.screen.height,
                    dpi: window.devicePixelRatio,
                    userAgent: navigator.userAgent
                }
            }),
            keepalive: true // Ensures the request finishes even if the player closes the tab
        }).catch(err => console.warn("[Analytics] Network error:", err));
    }

    // 2. Keep local history for debugging
    try {
        const history = JSON.parse(localStorage.getItem('analytics_history') || '[]');
        history.push({ event: eventName, payload, timestamp: Date.now() });
        localStorage.setItem('analytics_history', JSON.stringify(history.slice(-50))); // Keep the last 50 events locally
    } catch (e) {
        console.warn("Analytics storage failed:", e);
    }
}
